test('getCustomer finds customer with non-normalized id (mixed case and whitespace)', () => {
  const r = getCustomer(' c-007 ');
  assert.equal(r.ok, true);
  assert.equal(r.value.name, 'Halvorsen Architects');
});

test('mergeCustomers merges two customers', () => {
  const customers = listCustomers();
  const invoices = [];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, customers.length - 1);
  assert.ok(!result.value.customers.find((c) => c.id === 'C-001'));
  assert.ok(result.value.customers.find((c) => c.id === 'C-002'));
});

test('mergeCustomers redirects invoices from one customer to another', () => {
  const customers = listCustomers();
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r1.value, []);
  const invoices = [issued.value];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers reports SAME_CUSTOMER when merging same id', () => {
  const customers = listCustomers();
  const invoices = [];
  assert.deepEqual(mergeCustomers(customers, invoices, 'C-001', 'C-001'), { ok: false, error: 'SAME_CUSTOMER' });
});

test('mergeCustomers normalizes customer ids', () => {
  const customers = listCustomers();
  const invoices = [];
  const result = mergeCustomers(customers, invoices, 'c-001', 'C-002');
  assert.equal(result.ok, true);
  assert.ok(!result.value.customers.find((c) => c.id === 'C-001'));
});

test('mergeCustomers reports CUSTOMER_NOT_FOUND when fromId does not exist', () => {
  const customers = listCustomers();
  const invoices = [];
  assert.deepEqual(mergeCustomers(customers, invoices, 'C-999', 'C-001'), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers reports CUSTOMER_NOT_FOUND when intoId does not exist', () => {
  const customers = listCustomers();
  const invoices = [];
  assert.deepEqual(mergeCustomers(customers, invoices, 'C-001', 'C-999'), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers with multiple invoices from same customer', () => {
  const customers = listCustomers();
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const invoices = [issued1.value, issued2.value];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 2);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.equal(result.value.invoices[1].customerId, 'C-002');
});

test('mergeCustomers keeps invoices from other customers unchanged', () => {
  const customers = listCustomers();
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
