    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const invoices = [issued.value];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers with empty invoices array', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices.length, 0);
  assert.equal(result.value.customers.length, customers.length - 1);
});

test('mergeCustomers same id with different cases is not allowed', () => {
  const customers = listCustomers();
  const invoices = [];
  assert.deepEqual(mergeCustomers(customers, invoices, 'C-001', 'c-001'), { ok: false, error: 'SAME_CUSTOMER' });
});

test('mergeCustomers same id with whitespace is not allowed', () => {
  const customers = listCustomers();
  const invoices = [];
  assert.deepEqual(mergeCustomers(customers, invoices, 'C-001 ', ' C-001'), { ok: false, error: 'SAME_CUSTOMER' });
});

test('mergeCustomers from customer is gone', () => {
  const customers = listCustomers();
  const invoices = [];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.ok(!result.value.customers.find((c) => c.id === 'C-001'));
});

test('mergeCustomers other customers unchanged', () => {
  const customers = listCustomers();
  const invoices = [];
  const otherCustomers = customers.filter((c) => c.id !== 'C-001' && c.id !== 'C-002');
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  for (const other of otherCustomers) {
    assert.ok(result.value.customers.find((c) => c.id === other.id));
  }
});

test('mergeCustomers invoice customerId normalized', () => {
  const customers = listCustomers();
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const invoices = [issued.value];
  const result = mergeCustomers(customers, invoices, 'c-001', 'c-002');
  assert.equal(result.value.invoices[0].customerId, 'C-002');
});

test('mergeCustomers CUSTOMER_NOT_FOUND for partially missing customers', () => {
  const customers = [
    { id: 'C-001', name: 'Test', email: 'test@example.com', country: 'NL', tier: 'standard' },
  ];
  const invoices = [];
  assert.deepEqual(mergeCustomers(customers, invoices, 'C-001', 'C-002'), { ok: false, error: 'CUSTOMER_NOT_FOUND' });
});

test('mergeCustomers preserves other invoice properties', () => {
  const customers = listCustomers();
  const r = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const issued = issueInvoice(r.value, []);
  const invoices = [issued.value];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.value.invoices[0].number, issued.value.number);
  assert.equal(result.value.invoices[0].issueDate, issued.value.issueDate);
  assert.deepEqual(result.value.invoices[0].lines, issued.value.lines);
});

test('mergeCustomers multiple invoices from different customers', () => {
  const customers = listCustomers();
  const r1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const r2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-15',
    lines: [{ sku: 'DES-HOUR', qty: 1 }],
  });
  const r3 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-20',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const issued1 = issueInvoice(r1.value, []);
  const issued2 = issueInvoice(r2.value, ['INV-2026-0001']);
  const issued3 = issueInvoice(r3.value, ['INV-2026-0002']);
  const invoices = [issued1.value, issued2.value, issued3.value];
  const result = mergeCustomers(customers, invoices, 'C-001', 'C-003');
  assert.equal(result.value.invoices[0].customerId, 'C-003');
  assert.equal(result.value.invoices[1].customerId, 'C-002');
  assert.equal(result.value.invoices[2].customerId, 'C-003');
});

